const getDotY = <RawDatum extends StreamDatum>(
    datum: StreamLayerDatum,
    position: StreamDotsProps<RawDatum>['position']
) => {
    let y = datum.y2
    if (position === 'center') {
        y = datum.y1 + (datum.y2 - datum.y1) / 2
    } else if (position === 'start') {
        y = datum.y1
    }

    return y
};

